#[no_mangle]
pub unsafe extern "C" fn ipv6_converter(a:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if a.is_null()||n<2{return -1;}let v=std::slice::from_raw_parts(a,n);let(op,len)=(v[0],v[1]);if !((op==0&&len==4)||(op==1&&len==16))||n!=(2+len)as usize{return -1;}if v[2..].iter().any(|&x|!(0..=255).contains(&x)){return -1;}if op==1&&(v[2..12].iter().any(|&x|x!=0)||v[12]!=255||v[13]!=255){return -1;}let needed=if op==0{16}else{4};if out.is_null()||cap<needed{return -2;}let r=std::slice::from_raw_parts_mut(out,cap);if op==0{r[..10].fill(0);r[10]=255;r[11]=255;for i in 0..4{r[12+i]=v[2+i]as u8;}}else{for i in 0..4{r[i]=v[14+i]as u8;}}needed as i64}
